module hough #(
    parameter int NT = 16,
    parameter int NR = 96,
    parameter int ROFF = 48
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        pt_valid,
    input  logic [7:0]  pt_x,
    input  logic [7:0]  pt_y,
    output logic        busy,
    input  logic        clear,
    input  logic [3:0]  rd_theta,
    input  logic [6:0]  rd_rho,
    output logic [15:0] rd_cnt
);

    localparam integer DEPTH = NT * NR;

    (* ram_style = "block" *) logic [10:0] mem [0:DEPTH-1];

    logic clearing;
    logic [10:0] clear_index;

    logic issue_active;
    logic [3:0] issue_k;
    logic [4:0] saved_x, saved_y;

    wire launch = pt_valid && !busy && !clear;
    wire input_valid = launch || issue_active;
    wire [4:0] input_x = issue_active ? saved_x : pt_x[4:0];
    wire [4:0] input_y = issue_active ? saved_y : pt_y[4:0];
    wire [3:0] input_k = issue_active ? issue_k : 4'd0;

    function automatic logic signed [8:0] cos_coeff(input logic [3:0] k);
        begin
            case (k)
                4'd0:  cos_coeff =  9'sd128;
                4'd1:  cos_coeff =  9'sd126;
                4'd2:  cos_coeff =  9'sd118;
                4'd3:  cos_coeff =  9'sd106;
                4'd4:  cos_coeff =  9'sd91;
                4'd5:  cos_coeff =  9'sd71;
                4'd6:  cos_coeff =  9'sd49;
                4'd7:  cos_coeff =  9'sd25;
                4'd8:  cos_coeff =  9'sd0;
                4'd9:  cos_coeff = -9'sd25;
                4'd10: cos_coeff = -9'sd49;
                4'd11: cos_coeff = -9'sd71;
                4'd12: cos_coeff = -9'sd91;
                4'd13: cos_coeff = -9'sd106;
                4'd14: cos_coeff = -9'sd118;
                default: cos_coeff = -9'sd126;
            endcase
        end
    endfunction

    function automatic logic signed [8:0] sin_coeff(input logic [3:0] k);
        begin
            case (k)
                4'd0:  sin_coeff = 9'sd0;
                4'd1:  sin_coeff = 9'sd25;
                4'd2:  sin_coeff = 9'sd49;
                4'd3:  sin_coeff = 9'sd71;
                4'd4:  sin_coeff = 9'sd91;
                4'd5:  sin_coeff = 9'sd106;
                4'd6:  sin_coeff = 9'sd118;
                4'd7:  sin_coeff = 9'sd126;
                4'd8:  sin_coeff = 9'sd128;
                4'd9:  sin_coeff = 9'sd126;
                4'd10: sin_coeff = 9'sd118;
                4'd11: sin_coeff = 9'sd106;
                4'd12: sin_coeff = 9'sd91;
                4'd13: sin_coeff = 9'sd71;
                4'd14: sin_coeff = 9'sd49;
                default: sin_coeff = 9'sd25;
            endcase
        end
    endfunction

    // DSP operand, multiplier, and post-adder registers are intentionally
    // not reset so that Vivado can use the DSP48E1 pipeline registers.
    logic signed [5:0]  x_r, y_r;
    logic signed [8:0]  cos_r, sin_r;
    logic signed [14:0] m_x, m_y;
    logic signed [14:0] p_x, p_y;

    logic signed [15:0] sum_s4;
    logic [10:0] addr_s5;
    logic [10:0] addr6;
    logic [10:0] q_a, q_b;

    logic v1, v2, v3, v4, v5, v6;
    logic [3:0] k1, k2, k3, k4, k5, k6;

    always_ff @(posedge clk) begin
        if (input_valid) begin
            x_r   <= $signed({1'b0, input_x});
            y_r   <= $signed({1'b0, input_y});
            cos_r <= cos_coeff(input_k);
            sin_r <= sin_coeff(input_k);
        end

        m_x <= x_r * cos_r;
        m_y <= y_r * sin_r;
        p_x <= m_x + 15'sd0;
        p_y <= m_y + 15'sd0;

        sum_s4 <= {{1{p_x[14]}}, p_x} + {{1{p_y[14]}}, p_y};

        addr_s5 <= (k4 * NR)
                 + (($signed(sum_s4) + 16'sd64) >>> 7)
                 + ROFF;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            v1 <= 1'b0;
            v2 <= 1'b0;
            v3 <= 1'b0;
            v4 <= 1'b0;
            v5 <= 1'b0;
            v6 <= 1'b0;
            k1 <= 4'd0;
            k2 <= 4'd0;
            k3 <= 4'd0;
            k4 <= 4'd0;
            k5 <= 4'd0;
            k6 <= 4'd0;
            addr6 <= 11'd0;
        end else begin
            v1 <= input_valid;
            v2 <= v1;
            v3 <= v2;
            v4 <= v3;
            v5 <= v4;
            v6 <= v5;

            if (input_valid)
                k1 <= input_k;
            k2 <= k1;
            k3 <= k2;
            k4 <= k3;
            k5 <= k4;
            k6 <= k5;

            if (v5)
                addr6 <= addr_s5;
        end
    end

    wire [10:0] incremented_count =
        (q_a == 11'h7ff) ? q_a : (q_a + 11'd1);

    wire [12:0] rd_base =
        (rd_theta * NR);
    wire [12:0] rd_address_wide = rd_base + rd_rho;
    wire [10:0] rd_address = rd_address_wide[10:0];

    integer init_i;
    initial begin
        for (init_i = 0; init_i < DEPTH; init_i = init_i + 1)
            mem[init_i] = 11'd0;
    end

    // Port A performs the accumulator read/modify/write and clear sweep.
    // Port B provides synchronous shell readback.
    always_ff @(posedge clk) begin
        if (clearing) begin
            mem[clear_index] <= 11'd0;
        end else if (v6) begin
            mem[addr6] <= incremented_count;
        end

        if (!clearing && v5)
            q_a <= mem[addr_s5];

        if (rd_rho < NR)
            q_b <= mem[rd_address];
        else
            q_b <= 11'd0;
    end

    assign rd_cnt = {5'b0, q_b};

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy         <= 1'b0;
            clearing     <= 1'b0;
            clear_index  <= 11'd0;
            issue_active <= 1'b0;
            issue_k      <= 4'd0;
            saved_x      <= 5'd0;
            saved_y      <= 5'd0;
        end else begin
            if (clearing) begin
                if (clear_index == DEPTH-1) begin
                    clearing <= 1'b0;
                    busy     <= 1'b0;
                end else begin
                    clear_index <= clear_index + 11'd1;
                end
            end else begin
                if (busy && v6 && (k6 == 4'd15))
                    busy <= 1'b0;

                if (!busy) begin
                    if (clear) begin
                        clearing    <= 1'b1;
                        clear_index <= 11'd0;
                        busy        <= 1'b1;
                    end else if (pt_valid) begin
                        busy         <= 1'b1;
                        issue_active <= 1'b1;
                        issue_k      <= 4'd1;
                        saved_x      <= pt_x[4:0];
                        saved_y      <= pt_y[4:0];
                    end
                end

                if (issue_active) begin
                    if (issue_k == 4'd15)
                        issue_active <= 1'b0;
                    else
                        issue_k <= issue_k + 4'd1;
                end
            end
        end
    end

endmodule
```
NOTE: Point updates take 16 direction-issue clocks plus 6 pipeline clocks; expected resources are 2 DSP48E1s, one 1536×11 BRAM, and small control/address logic.

