```systemverilog
module hough #(
    parameter int NT = 16,
    parameter int NR = 96,
    parameter int ROFF = 48
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        pt_valid,
    input  logic [7:0]  pt_x,
    input  logic [7:0]  pt_y,
    output logic        busy,
    input  logic        clear,
    input  logic [3:0]  rd_theta,
    input  logic [6:0]  rd_rho,
    output logic [15:0] rd_cnt
);

    localparam int MEM_DEPTH = NT * NR;
    localparam int AW = (MEM_DEPTH <= 2) ? 1 : $clog2(MEM_DEPTH);

    logic [10:0] mem [0:MEM_DEPTH-1];

    initial begin : init_accumulator
        integer i;
        for (i = 0; i < MEM_DEPTH; i = i + 1)
            mem[i] = 11'd0;
    end

    function automatic logic signed [8:0] cos_lut(input logic [3:0] k);
        case (k)
            4'd0:  cos_lut =  9'sd128;
            4'd1:  cos_lut =  9'sd126;
            4'd2:  cos_lut =  9'sd118;
            4'd3:  cos_lut =  9'sd106;
            4'd4:  cos_lut =   9'sd91;
            4'd5:  cos_lut =   9'sd71;
            4'd6:  cos_lut =   9'sd49;
            4'd7:  cos_lut =   9'sd25;
            4'd8:  cos_lut =    9'sd0;
            4'd9:  cos_lut =  -9'sd25;
            4'd10: cos_lut =  -9'sd49;
            4'd11: cos_lut =  -9'sd71;
            4'd12: cos_lut =  -9'sd91;
            4'd13: cos_lut = -9'sd106;
            4'd14: cos_lut = -9'sd118;
            default: cos_lut = -9'sd126;
        endcase
    endfunction

    function automatic logic signed [8:0] sin_lut(input logic [3:0] k);
        case (k)
            4'd0:  sin_lut =    9'sd0;
            4'd1:  sin_lut =   9'sd25;
            4'd2:  sin_lut =   9'sd49;
            4'd3:  sin_lut =   9'sd71;
            4'd4:  sin_lut =   9'sd91;
            4'd5:  sin_lut =  9'sd106;
            4'd6:  sin_lut =  9'sd118;
            4'd7:  sin_lut =  9'sd126;
            4'd8:  sin_lut =  9'sd128;
            4'd9:  sin_lut =  9'sd126;
            4'd10: sin_lut =  9'sd118;
            4'd11: sin_lut =  9'sd106;
            4'd12: sin_lut =   9'sd91;
            4'd13: sin_lut =   9'sd71;
            4'd14: sin_lut =   9'sd49;
            default: sin_lut =   9'sd25;
        endcase
    endfunction

    function automatic logic [6:0] projected_bin(
        input logic signed [18:0] projection
    );
        logic signed [18:0] rounded_rho;
        begin
            rounded_rho = (projection + 19'sd64) >>> 7;
            projected_bin = rounded_rho + ROFF;
        end
    endfunction

    logic [4:0] x_hold, y_hold;
    logic       launch_active;
    logic [3:0] launch_dir;
    logic       clear_active;
    logic [AW-1:0] clear_addr;

    logic signed [8:0] x_cos_a_r, x_cos_b_r;
    logic signed [8:0] y_sin_a_r, y_sin_b_r;
    logic signed [17:0] x_product_m, y_product_m;
    logic signed [17:0] x_product_p, y_product_p;
    logic signed [18:0] projection_sum;
    logic [AW-1:0] address_stage5;

    logic [3:0] dir_stage1, dir_stage2, dir_stage3, dir_stage4;
    logic valid_stage1, valid_stage2, valid_stage3, valid_stage4;
    logic valid_stage5, valid_stage6, valid_stage7;
    logic final_stage1, final_stage2, final_stage3, final_stage4;
    logic final_stage5, final_stage6, final_stage7;

    logic [AW-1:0] ram_read_addr_q;
    logic [10:0] ram_q;
    logic [AW-1:0] write_addr;
    logic [10:0] write_data;
    logic readback_valid;

    logic [AW-1:0] readback_addr;
    always_comb begin
        readback_addr = rd_theta * NR + rd_rho;
    end

    // DSP input, multiplier, and post-multiply pipeline registers. These
    // intentionally have no reset so Vivado can map them into DSP48E1s.
    always_ff @(posedge clk) begin
        if (launch_active) begin
            x_cos_a_r <= $signed({4'b0000, x_hold});
            x_cos_b_r <= cos_lut(launch_dir);
            y_sin_a_r <= $signed({4'b0000, y_hold});
            y_sin_b_r <= sin_lut(launch_dir);
        end

        x_product_m <= x_cos_a_r * x_cos_b_r;
        y_product_m <= y_sin_a_r * y_sin_b_r;

        x_product_p <= x_product_m;
        y_product_p <= y_product_m;

        projection_sum <=
            {{1{x_product_p[17]}}, x_product_p} +
            {{1{y_product_p[17]}}, y_product_p};

        address_stage5 <= dir_stage4 * NR + projected_bin(projection_sum);
    end

    // Valid, direction, and final-bin tags follow the six-stage datapath.
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_stage1 <= 1'b0;
            valid_stage2 <= 1'b0;
            valid_stage3 <= 1'b0;
            valid_stage4 <= 1'b0;
            valid_stage5 <= 1'b0;
            valid_stage6 <= 1'b0;
            valid_stage7 <= 1'b0;

            final_stage1 <= 1'b0;
            final_stage2 <= 1'b0;
            final_stage3 <= 1'b0;
            final_stage4 <= 1'b0;
            final_stage5 <= 1'b0;
            final_stage6 <= 1'b0;
            final_stage7 <= 1'b0;

            dir_stage1 <= 4'd0;
            dir_stage2 <= 4'd0;
            dir_stage3 <= 4'd0;
            dir_stage4 <= 4'd0;

            write_addr <= '0;
            write_data <= 11'd0;
        end else begin
            valid_stage1 <= launch_active;
            valid_stage2 <= valid_stage1;
            valid_stage3 <= valid_stage2;
            valid_stage4 <= valid_stage3;
            valid_stage5 <= valid_stage4;
            valid_stage6 <= valid_stage5;
            valid_stage7 <= valid_stage6;

            final_stage1 <= launch_active && (launch_dir == 4'd15);
            final_stage2 <= final_stage1;
            final_stage3 <= final_stage2;
            final_stage4 <= final_stage3;
            final_stage5 <= final_stage4;
            final_stage6 <= final_stage5;
            final_stage7 <= final_stage6;

            if (launch_active)
                dir_stage1 <= launch_dir;
            dir_stage2 <= dir_stage1;
            dir_stage3 <= dir_stage2;
            dir_stage4 <= dir_stage3;

            if (valid_stage6) begin
                write_addr <= ram_read_addr_q;
                if (ram_q == 11'h7ff)
                    write_data <= 11'h7ff;
                else
                    write_data <= ram_q + 11'd1;
            end
        end
    end

    // Single synchronous-read, single-write accumulator RAM.
    (* ram_style = "block" *)
    always_ff @(posedge clk) begin
        if (clear_active) begin
            mem[clear_addr] <= 11'd0;
            ram_q <= 11'd0;
        end else begin
            if (valid_stage7)
                mem[write_addr] <= write_data;

            if (valid_stage5) begin
                ram_q <= mem[address_stage5];
                ram_read_addr_q <= address_stage5;
            end else if (rd_rho < NR) begin
                ram_q <= mem[readback_addr];
            end else begin
                ram_q <= 11'd0;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy          <= 1'b0;
            launch_active <= 1'b0;
            launch_dir    <= 4'd0;
            x_hold        <= 5'd0;
            y_hold        <= 5'd0;
            clear_active  <= 1'b0;
            clear_addr    <= '0;
            readback_valid <= 1'b0;
            rd_cnt        <= 16'd0;
        end else begin
            if (clear_active) begin
                if (clear_addr == MEM_DEPTH-1) begin
                    clear_active <= 1'b0;
                    clear_addr   <= '0;
                end else begin
                    clear_addr <= clear_addr + 1'b1;
                end
            end else if (clear && !busy) begin
                clear_active <= 1'b1;
                clear_addr   <= '0;
                rd_cnt       <= 16'd0;
            end

            if (launch_active) begin
                if (launch_dir == 4'd15)
                    launch_active <= 1'b0;
                else
                    launch_dir <= launch_dir + 1'b1;
            end

            if (valid_stage7 && final_stage7)
                busy <= 1'b0;

            if (!clear_active && !clear && !busy && !launch_active &&
                pt_valid) begin
                x_hold        <= pt_x[4:0];
                y_hold        <= pt_y[4:0];
                launch_dir    <= 4'd0;
                launch_active <= 1'b1;
                busy          <= 1'b1;
            end

            if (valid_stage5 || clear_active)
                readback_valid <= 1'b0;
            else
                readback_valid <= 1'b1;

            if (readback_valid)
                rd_cnt <= {5'd0, ram_q};
            if (clear_active)
                rd_cnt <= 16'd0;
        end
    end

endmodule
