```systemverilog
module hough #(
    parameter int NT = 16,
    parameter int NR = 96,
    parameter int ROFF = 48
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        pt_valid,
    input  logic [7:0]  pt_x,
    input  logic [7:0]  pt_y,
    output logic        busy,
    input  logic        clear,
    input  logic [3:0]  rd_theta,
    input  logic [6:0]  rd_rho,
    output logic [15:0] rd_cnt
);

    localparam int MEM_DEPTH = NT * NR;
    localparam int ADDR_W = (MEM_DEPTH <= 2) ? 1 : $clog2(MEM_DEPTH);

    (* ram_style = "block" *) logic [10:0] mem [0:MEM_DEPTH-1];

    logic clearing;
    logic [ADDR_W-1:0] clear_idx;

    logic issuing;
    logic [3:0] issue_theta;
    logic [4:0] point_x, point_y;
    logic issue_fire;

    logic signed [8:0] cos_coeff, sin_coeff;
    logic signed [8:0] x_a_r, cos_b_r;
    logic signed [8:0] y_a_r, sin_b_r;
    logic signed [17:0] x_m, y_m;
    logic signed [17:0] x_p, y_p;
    logic signed [18:0] sum4;
    logic signed [18:0] rho_calc;
    logic signed [18:0] bin_calc;

    logic [3:0] theta1, theta2, theta3, theta4;
    logic [ADDR_W-1:0] addr5, addr6, inc_addr;
    logic last5, last6, inc_last;
    logic [6:0] bin_index;

    logic v1, v2, v3, v4, v5, v6, v7;
    logic ext_d1;
    logic [10:0] mem_q;
    logic [10:0] inc_data;

    logic [ADDR_W-1:0] ext_addr, read_addr;

    assign issue_fire = issuing && !clearing;

    always_comb begin
        cos_coeff = 9'sd0;
        sin_coeff = 9'sd0;
        case (issue_theta)
            4'd0:  begin cos_coeff =  9'sd128; sin_coeff =  9'sd0;   end
            4'd1:  begin cos_coeff =  9'sd126; sin_coeff =  9'sd25;  end
            4'd2:  begin cos_coeff =  9'sd118; sin_coeff =  9'sd49;  end
            4'd3:  begin cos_coeff =  9'sd106; sin_coeff =  9'sd71;  end
            4'd4:  begin cos_coeff =  9'sd91;  sin_coeff =  9'sd91;  end
            4'd5:  begin cos_coeff =  9'sd71;  sin_coeff =  9'sd106; end
            4'd6:  begin cos_coeff =  9'sd49;  sin_coeff =  9'sd118; end
            4'd7:  begin cos_coeff =  9'sd25;  sin_coeff =  9'sd126; end
            4'd8:  begin cos_coeff =  9'sd0;   sin_coeff =  9'sd128; end
            4'd9:  begin cos_coeff = -9'sd25;  sin_coeff =  9'sd126; end
            4'd10: begin cos_coeff = -9'sd49;  sin_coeff =  9'sd118; end
            4'd11: begin cos_coeff = -9'sd71;  sin_coeff =  9'sd106; end
            4'd12: begin cos_coeff = -9'sd91;  sin_coeff =  9'sd91;  end
            4'd13: begin cos_coeff = -9'sd106; sin_coeff =  9'sd71;  end
            4'd14: begin cos_coeff = -9'sd118; sin_coeff =  9'sd49;  end
            4'd15: begin cos_coeff = -9'sd126; sin_coeff =  9'sd25;  end
        endcase
    end

    always_comb begin
        rho_calc = ($signed(sum4) + 19'sd64) >>> 7;
        bin_calc = rho_calc + $signed(ROFF);
        bin_index = bin_calc[6:0];
        ext_addr = (rd_theta * NR) + rd_rho;
        if (v5)
            read_addr = addr5;
        else
            read_addr = ext_addr;
    end

    // DSP input operand registers (stage 1).
    always_ff @(posedge clk) begin
        if (issue_fire) begin
            x_a_r   <= $signed({4'b0000, point_x});
            cos_b_r <= cos_coeff;
            y_a_r   <= $signed({4'b0000, point_y});
            sin_b_r <= sin_coeff;
            theta1  <= issue_theta;
        end
    end

    // DSP multiplier and post-multiply pipeline registers (stages 2 and 3).
    always_ff @(posedge clk) begin
        x_m <= x_a_r * cos_b_r;
        y_m <= y_a_r * sin_b_r;
        x_p <= x_m;
        y_p <= y_m;
        theta2 <= theta1;
        theta3 <= theta2;
    end

    // Projection sum (stage 4), then rounding and bin selection (stage 5).
    always_ff @(posedge clk) begin
        sum4 <= x_p + y_p;
        theta4 <= theta3;
        addr5 <= (theta4 * NR) + bin_index;
        last5 <= (theta4 == 4'd15);
    end

    // Synchronous BRAM read and accumulator write ports.
    always_ff @(posedge clk) begin
        mem_q <= mem[read_addr];

        if (clearing)
            mem[clear_idx] <= 11'd0;
        else if (v7)
            mem[inc_addr] <= inc_data;
    end

    // BRAM-read address pipeline and saturating increment.
    always_ff @(posedge clk) begin
        addr6    <= addr5;
        last6    <= last5;
        inc_addr <= addr6;
        inc_last <= last6;

        if (v6) begin
            if (mem_q == 11'h7ff)
                inc_data <= mem_q;
            else
                inc_data <= mem_q + 11'd1;
        end
    end

    // Control, point issue, clear sweep, and pipeline-valid tracking.
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy       <= 1'b0;
            clearing   <= 1'b0;
            clear_idx  <= '0;
            issuing    <= 1'b0;
            issue_theta <= 4'd0;
            point_x    <= 5'd0;
            point_y    <= 5'd0;
            v1         <= 1'b0;
            v2         <= 1'b0;
            v3         <= 1'b0;
            v4         <= 1'b0;
            v5         <= 1'b0;
            v6         <= 1'b0;
            v7         <= 1'b0;
            ext_d1     <= 1'b0;
            rd_cnt     <= 16'd0;
        end else begin
            v1 <= issue_fire;
            v2 <= v1;
            v3 <= v2;
            v4 <= v3;
            v5 <= v4;
            v6 <= v5;
            v7 <= v6;

            ext_d1 <= !v5 && !clearing;
            if (ext_d1)
                rd_cnt <= {5'd0, mem_q};

            if (clearing) begin
                if (clear_idx == MEM_DEPTH-1) begin
                    clearing  <= 1'b0;
                    clear_idx <= '0;
                    busy      <= 1'b0;
                end else begin
                    clear_idx <= clear_idx + 1'b1;
                end
            end else if (busy) begin
                if (issue_fire) begin
                    if (issue_theta == 4'd15)
                        issuing <= 1'b0;
                    else
                        issue_theta <= issue_theta + 1'b1;
                end

                if (v7 && inc_last) begin
                    busy <= 1'b0;
                    issuing <= 1'b0;
                end
            end else if (clear) begin
                busy      <= 1'b1;
                clearing  <= 1'b1;
                clear_idx <= '0;
                issuing   <= 1'b0;
            end else if (pt_valid) begin
                busy        <= 1'b1;
                point_x     <= pt_x[4:0];
                point_y     <= pt_y[4:0];
                issue_theta <= 4'd0;
                issuing     <= 1'b1;
            end
        end
    end

