            4'd1:  cos_coeff =  8'sd126;
            4'd2:  cos_coeff =  8'sd118;
            4'd3:  cos_coeff =  8'sd106;
            4'd4:  cos_coeff =  8'sd91;
            4'd5:  cos_coeff =  8'sd71;
            4'd6:  cos_coeff =  8'sd49;
