            dir2 <= '0;
            dir3 <= '0;
            dir4 <= '0;
            last1 <= 1'b0;
            last2 <= 1'b0;
            last3 <= 1'b0;
            last4 <= 1'b0;
            last5 <= 1'b0;
            last6 <= 1'b0;
